#include <bits/stdc++.h>
using namespace std;

vector<string> rotate90(const vector<string>& grid) {
    int n = grid.size();
    vector<string> result(n, string(n, ' '));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            result[j][n - 1 - i] = grid[i][j];
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<string> source(n), target(n);
    for (auto& row : source)
        cin >> row;
    for (auto& row : target)
        cin >> row;

    vector<string> current = source;

    for (int rotation = 0; rotation < 4; ++rotation) {
        if (current == target) {
            cout << "YES";
            return 0;
        }

        vector<string> reflected = current;
        for (auto& row : reflected)
            reverse(row.begin(), row.end());

        if (reflected == target) {
            cout << "YES";
            return 0;
        }

        current = rotate90(current);
    }

    cout << "NO";
    return 0;
}
